def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev_bids = []
    needy_count = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                needy_count += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(bid)
                    if opp.get('budget', 0) >= bid:
                        strong_prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    total_players = len(alive) + 1
    expected_share = supply / float(total_players)
    scarcity = expected_share < WATER_REQ

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    strong_high = max(strong_prev_bids) if strong_prev_bids else highest_prev

    if hp <= 2 or no_water_days >= 2:
        bid = max(62.0, strong_high + 2.0)
    elif hp <= 4 or no_water_days >= 1:
        if scarcity:
            bid = max(54.0, avg_prev + 3.0)
        else:
            bid = max(34.0, avg_prev * 0.55)
    else:
        if scarcity:
            if supply <= 17:
                bid = max(46.0, min(strong_high + 1.5, 78.0))
            elif supply <= 20:
                bid = max(38.0, min(avg_prev * 0.72 + 2.0, 68.0))
            else:
                bid = max(30.0, min(avg_prev * 0.58 + 1.0, 58.0))
        else:
            bid = 18.0 if day < 8 else 24.0

    if needy_count >= 2 and scarcity:
        bid += 6.0
    elif needy_count >= 1 and scarcity:
        bid += 3.0

    rich_opponents = 0
    for opp in alive:
        if opp.get('budget', 0) > budget:
            rich_opponents += 1
    if rich_opponents >= 3 and hp >= 5 and no_water_days == 0:
        bid -= 4.0

    if day >= 8 and hp >= 5 and budget > 120:
        bid += 4.0

    bid = max(0.0, min(float(budget), bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        # If alone, bid conservatively to stay solvent
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate whether we likely need to secure at least one unit of water to avoid no-water days
    # (We don't know today's hidden bids; this is a heuristic.)
    no_water_days = int(my_status.get('no_water_days', 0))
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    # Base bid: aim for a mid value that often beats low bidders but doesn't match overbidders.
    # Use supply to scale: higher supply reduces urgency.
    supply_factor = (float(supply) - 15.0) / (25.0 - 15.0) if (25.0 - 15.0) != 0 else 0.5
    supply_factor = max(0.0, min(1.0, supply_factor))

    # If opponents were bidding extremely high yesterday, they likely force contention.
    # Cindy's pattern suggests some agents can sustain high bids.
    urgent_pressure = highest_prev_bid >= DAILY_SALARY * 1.15  # ~103.5

    # If I'm low hp or have accumulated no-water days, I must raise bids.
    critical = (hp <= 2.5) or (no_water_days >= 2)

    # Compute target bid
    if urgent_pressure:
        if critical:
            target = DAILY_SALARY * 0.95
        else:
            # Slightly under the overbid to conserve budget
            target = max(DAILY_SALARY * 0.65, min(DAILY_SALARY * 0.85, highest_prev_bid * 0.75))
    else:
        if critical:
            target = DAILY_SALARY * 0.85
        else:
            # Mid bid; scale down when supply is higher
            target = DAILY_SALARY * (0.55 - 0.15 * supply_factor)
            target = max(DAILY_SALARY * 0.35, target)

    # Don't exceed budget; also avoid bidding negative
    bid = max(0.0, min(budget, float(target)))

    # If budget is very low, still bid enough to have a chance (but capped)
    if budget < DAILY_SALARY * 0.2:
        bid = max(0.0, min(budget, DAILY_SALARY * 0.1))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opps = [o for o in opponents_status.values() if o['alive']]
    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace')
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
    else:
        max_prev = 0.0
        avg_prev = 0.0

    if hp <= 2:
        bid = min(budget, DAILY_SALARY * 0.9)
        if max_prev > 0 and bid <= max_prev:
            bid = min(budget, max_prev + 1)
        return bid
    elif hp <= 5:
        target = max_prev + 5 if max_prev > 0 else DAILY_SALARY * 0.5
        bid = min(budget, target)
        bid = min(bid, DAILY_SALARY * 0.95)
        bid = max(bid, DAILY_SALARY * 0.1)
        return bid
